"use client";
/* Cookie, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Cookie(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("cookie"); }, []);
  return React.createElement("piix-sprite", { "name": "cookie", ...piixAttrs(props) });
}

export default Cookie;
